const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "postgresql",
  "inlineSchema": "// =============================================================================\n// PRISMA SCHEMA — PHASE 1 FOUNDATION (auth + RBAC + audit generik)\n// ID strategy: CUID string untuk semua entity utama (konsisten, URL-friendly,\n// tidak membocorkan urutan data seperti auto-increment integer).\n// Database PostgreSQL disambungkan pada Phase 2; aplikasi Phase 1 berjalan\n// dengan data dummy yang struktur-nya зеркалит schema ini.\n// =============================================================================\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id             String          @id @default(cuid())\n  username       String          @unique\n  email          String?         @unique\n  passwordHash   String\n  employeeId     String?         @unique\n  isActive       Boolean         @default(true)\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n  employee       Employee?       @relation(fields: [employeeId], references: [id])\n  roles          UserRole[]\n  auditLogs      AuditLog[]\n  stockMovements StockMovement[]\n  pickings       Picking[]\n  shipments      Shipment[]\n  returns        Return[]\n\n  @@map(\"users\")\n}\n\nmodel Role {\n  id          String           @id @default(cuid())\n  code        String           @unique\n  name        String\n  description String?\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n  users       UserRole[]\n  permissions RolePermission[]\n\n  @@map(\"roles\")\n}\n\nmodel Permission {\n  id          String           @id @default(cuid())\n  code        String           @unique\n  name        String\n  description String?\n  module      String\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n  roles       RolePermission[]\n\n  @@map(\"permissions\")\n}\n\nmodel UserRole {\n  userId    String\n  roleId    String\n  createdAt DateTime @default(now())\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role      Role     @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@id([userId, roleId])\n  @@map(\"user_roles\")\n}\n\nmodel RolePermission {\n  roleId       String\n  permissionId String\n  createdAt    DateTime   @default(now())\n  role         Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission   Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, permissionId])\n  @@map(\"role_permissions\")\n}\n\n/// Jejak audit GENERIK lintas modul (append-only: tanpa updatedAt).\n/// Diisi Phase 2+ dari server actions (user, action, module, recordId,\n/// snapshot before/after sebagai JSON).\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  userId    String?\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  action    String\n  module    String\n  recordId  String?\n  before    Json?\n  after     Json?\n  createdAt DateTime @default(now())\n\n  @@index([module, createdAt])\n  @@index([userId, createdAt])\n  @@map(\"audit_logs\")\n}\n\n// =============================================================================\n// PHASE 2 — TABEL BISNIS\n// Hasil analisis 8 dokumen Excel client (lihat docs/DATABASE-SCHEMA.md).\n// Domain: Master → Produksi → Persediaan → Penjualan → HR → Keuangan.\n// Uang: satuan Rupiah bulat (Int). Saldo/kas berjalan dihitung aplikasi.\n// =============================================================================\n\nenum ProductType {\n  GARMENT // pakaian, punya ukuran\n  ACCESSORY // barang tanpa ukuran (mis. plastik packing)\n}\n\nenum StockMovementType {\n  PRODUCTION_IN // hasil produksi masuk gudang\n  PRODUCTION_OUT // pengeluaran bahan utk produksi\n  SALE_SHIPMENT // pengurangan stok saat pengiriman (actual qty)\n  RETURN_IN // penerimaan barang retur (layak jual)\n  ADJUSTMENT_IN // koreksi bertambah\n  ADJUSTMENT_OUT // koreksi berkurang\n}\n\nenum SalesChannel {\n  SHOPEE\n  TIKTOK\n  LIVE // host live streaming\n  DROPSHIP\n  RESELLER\n  OFFLINE\n}\n\nenum OrderStatus {\n  PENDING\n  PICKING\n  PICKED\n  READY_TO_SHIP\n  SHIPPED\n  COMPLETED\n  CANCELLED\n  RETURNED\n}\n\n/// Kode presensi — pemetaan sheet Excel: J1=WORK, J2=LEAVE (ijin/sakit/alfa),\n/// J3=MENSTRUAL (MERAH), J4=OVERTIME (LEMBUR).\nenum AttendanceCode {\n  WORK\n  LEAVE\n  SICK\n  ABSENT\n  MENSTRUAL\n  OVERTIME\n}\n\nenum CashFlowType {\n  IN // kas masuk (debet)\n  OUT // kas keluar (kredit)\n}\n\n/// Kategori kas dari sheet cash Flow (Shopee/TikTok tarik saldo, beli bahan, dll).\nenum CashCategory {\n  SALES\n  WITHDRAWAL // tarik saldo marketplace\n  MATERIAL // beli bahan\n  PAYROLL\n  OPERATIONAL // listrik, laundry, makan, dll\n  OTHER\n}\n\nenum PayrollStatus {\n  DRAFT\n  PAID\n}\n\n// ---------------------------------------------------------------------------\n// ENTITAS & MASTER\n// ---------------------------------------------------------------------------\n\n/// Brand/entitas usaha: Kebaya Authentik, Glamore Kebaya.\nmodel Entity {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  name      String\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  cashTransactions CashTransaction[]\n  salesOrders      SalesOrder[]\n\n  @@map(\"entities\")\n}\n\n/// Produk/katalog — sheet DATA + DROPSHIP \"NAMA PRODUK\".\n/// code = kode pendek dropship (G, GS, KB, ...).\nmodel Product {\n  id        String      @id @default(cuid())\n  code      String      @unique\n  name      String\n  type      ProductType @default(GARMENT)\n  basePrice Int         @default(0) // harga katalog\n  hpp       Int? // HPP — SENSITIF (butuh HPP_VIEW); flat utk fase ini\n  isActive  Boolean     @default(true)\n  createdAt DateTime    @default(now())\n  updatedAt DateTime    @updatedAt\n\n  sizes          ProductSize[]\n  stock          Stock[]\n  resellerPrices ResellerPrice[]\n  cuttings       Cutting[]\n  sewings        Sewing[]\n  orderItems     SalesOrderItem[]\n\n  @@map(\"products\")\n}\n\n/// Warna — daftar referensi TUNGGAL (memperbaiki BURGUNDI/BERGUNDI, MARON/MAROON, dll).\nmodel Color {\n  id        String   @id @default(cuid())\n  code      String   @unique // normalisasi huruf besar: MAHOGANY, BURGUNDY\n  name      String\n  hex       String? // pratinjau warna UI (#RRGGBB)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  stock         Stock[]\n  fabricStock   FabricStock[]\n  materialUsage MaterialUsage[]\n  purchases     MaterialPurchase[]\n  cuttings      Cutting[]\n  sewings       Sewing[]\n  orderItems    SalesOrderItem[]\n\n  @@map(\"colors\")\n}\n\n/// Ukuran — dua sistem digabung: apparel (S,M,L,XL) & numerik (4,6,8,10,12,14).\n/// Barang tanpa ukuran (ACCESSORY) memakai ukuran \"ALL\" (di-seed).\nmodel Size {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  label     String\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  products     ProductSize[]\n  stock        Stock[]\n  cuttingItems CuttingItem[]\n  sewingItems  SewingItem[]\n  orderItems   SalesOrderItem[]\n\n  @@map(\"sizes\")\n}\n\n/// Ukuran yang berlaku per produk (ukuran mengikuti model — temuan #3).\nmodel ProductSize {\n  productId String\n  sizeId    String\n  sortOrder Int     @default(0)\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  size      Size    @relation(fields: [sizeId], references: [id], onDelete: Cascade)\n\n  @@id([productId, sizeId])\n  @@map(\"product_sizes\")\n}\n\nmodel Supplier {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  name      String\n  phone     String?\n  address   String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  purchases MaterialPurchase[]\n\n  @@map(\"suppliers\")\n}\n\n/// Karyawan — sheet DATA (penjahit, tim) + presensi HITUNGAN GAJIH.\n/// posisi: CUTTING, SEWIST, HOST_LIVE, WAREHOUSE, SALES, ADMIN.\nmodel Employee {\n  id                 String   @id @default(cuid())\n  code               String   @unique\n  name               String\n  position           String\n  baseSalary         Int      @default(0) // gaji pokok (rumus: 1.500.000)\n  transportAllowance Int      @default(0) // tunjangan transport (100.000)\n  workdayBasis       Int      @default(25) // dasar hitung gaji\n  isActive           Boolean  @default(true)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  user        User?\n  teamMembers ProductionTeamMember[]\n  sewings     Sewing[]\n  attendances Attendance[]\n  payrolls    Payroll[]\n\n  @@map(\"employees\")\n}\n\n// ---------------------------------------------------------------------------\n// PRODUKSI\n// ---------------------------------------------------------------------------\n\n/// Tim cutting (pasangan: JIMAT/FERRY, RANGGA/GILANG, ...).\nmodel ProductionTeam {\n  id        String   @id @default(cuid())\n  name      String   @unique\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  members      ProductionTeamMember[]\n  cuttings     Cutting[]\n  materialUsed MaterialUsage[]\n\n  @@map(\"production_teams\")\n}\n\nmodel ProductionTeamMember {\n  teamId     String\n  employeeId String\n  team       ProductionTeam @relation(fields: [teamId], references: [id], onDelete: Cascade)\n  employee   Employee       @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n  createdAt  DateTime       @default(now())\n\n  @@id([teamId, employeeId])\n  @@map(\"production_team_members\")\n}\n\n/// Jenis kain — BROKAT, TILLE, FUKORO, PURING, ROK BATIK, ...\nmodel Fabric {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  name      String\n  unit      String   @default(\"ROLL\") // ROLL / METER / YARD\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  stock     FabricStock[]\n  usage     MaterialUsage[]\n  purchases MaterialPurchase[]\n\n  @@map(\"fabrics\")\n}\n\n/// Stok bahan = jenis kain × warna (sheet BAHAN, matriks STOCK).\nmodel FabricStock {\n  id        String   @id @default(cuid())\n  fabricId  String\n  colorId   String\n  qty       Decimal  @default(0) @db.Decimal(12, 2)\n  updatedAt DateTime @updatedAt\n  createdAt DateTime @default(now())\n  fabric    Fabric   @relation(fields: [fabricId], references: [id], onDelete: Cascade)\n  color     Color    @relation(fields: [colorId], references: [id], onDelete: Cascade)\n\n  @@unique([fabricId, colorId])\n  @@map(\"fabric_stocks\")\n}\n\n/// Pengeluaran bahan — sheet BAHAN: tanggal, tim, kain, warna, roll, jumlah.\nmodel MaterialUsage {\n  id        String   @id @default(cuid())\n  date      DateTime\n  teamId    String\n  fabricId  String\n  colorId   String\n  roll      Int      @default(0)\n  qty       Int      @default(0) // jumlah (meter/yard terpakai)\n  note      String?\n  createdAt DateTime @default(now())\n\n  team   ProductionTeam @relation(fields: [teamId], references: [id])\n  fabric Fabric         @relation(fields: [fabricId], references: [id])\n  color  Color          @relation(fields: [colorId], references: [id])\n\n  @@index([date])\n  @@map(\"material_usages\")\n}\n\n/// Pembelian bahan ke supplier (dari alur kas \"Beli Puring ...\").\nmodel MaterialPurchase {\n  id         String   @id @default(cuid())\n  date       DateTime\n  supplierId String\n  fabricId   String\n  colorId    String\n  qty        Decimal  @db.Decimal(12, 2)\n  unitPrice  Int      @default(0)\n  total      Int      @default(0)\n  note       String?\n  createdAt  DateTime @default(now())\n\n  supplier Supplier @relation(fields: [supplierId], references: [id])\n  fabric   Fabric   @relation(fields: [fabricId], references: [id])\n  color    Color    @relation(fields: [colorId], references: [id])\n\n  @@index([date])\n  @@map(\"material_purchases\")\n}\n\n/// Cutting — sheet CUTTING NEW: tanggal, tim, model, warna, roll, lebih size S.\nmodel Cutting {\n  id        String   @id @default(cuid())\n  date      DateTime\n  teamId    String\n  productId String\n  colorId   String\n  roll      Int      @default(0)\n  surplus   Int      @default(0) // \"Lebih size S\"\n  note      String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  team    ProductionTeam @relation(fields: [teamId], references: [id])\n  product Product        @relation(fields: [productId], references: [id])\n  color   Color          @relation(fields: [colorId], references: [id])\n  items   CuttingItem[]\n\n  @@index([date])\n  @@index([productId, colorId])\n  @@map(\"cuttings\")\n}\n\n/// Qty cutting per ukuran (4/S, 6/M, 8/L, 10/XL, 12, 14).\nmodel CuttingItem {\n  cuttingId String\n  sizeId    String\n  qty       Int     @default(0)\n  cutting   Cutting @relation(fields: [cuttingId], references: [id], onDelete: Cascade)\n  size      Size    @relation(fields: [sizeId], references: [id], onDelete: Cascade)\n\n  @@id([cuttingId, sizeId])\n  @@map(\"cutting_items\")\n}\n\n/// Jahit + setoran piece-rate — sheet PENJAHIT:\n/// No Surat Jalan, penjahit, tgl setor, jumlah disetor, selisih −/+.\n/// delta dihitung aplikasi: total item − setorQty.\nmodel Sewing {\n  id         String    @id @default(cuid())\n  date       DateTime\n  productId  String\n  colorId    String\n  sewistId   String // karyawan penjahit\n  suratJalan String?\n  setorDate  DateTime?\n  setorQty   Int? // jumlah pcs disetor\n  note       String?\n  createdAt  DateTime  @default(now())\n  updatedAt  DateTime  @updatedAt\n\n  product Product      @relation(fields: [productId], references: [id])\n  color   Color        @relation(fields: [colorId], references: [id])\n  sewist  Employee     @relation(fields: [sewistId], references: [id])\n  items   SewingItem[]\n\n  @@index([date])\n  @@index([sewistId, date])\n  @@map(\"sewings\")\n}\n\nmodel SewingItem {\n  sewingId String\n  sizeId   String\n  qty      Int    @default(0)\n  sewing   Sewing @relation(fields: [sewingId], references: [id], onDelete: Cascade)\n  size     Size   @relation(fields: [sizeId], references: [id], onDelete: Cascade)\n\n  @@id([sewingId, sizeId])\n  @@map(\"sewing_items\")\n}\n\n// ---------------------------------------------------------------------------\n// PERSEDIAAN (barang jadi)\n// ---------------------------------------------------------------------------\n\n/// Stok barang jadi — kunci (produk, warna, ukuran). Ukuran \"ALL\" utk ACCESSORY.\nmodel Stock {\n  id        String   @id @default(cuid())\n  productId String\n  colorId   String? // null = barang tanpa warna (aksesori)\n  sizeId    String? // null = barang tanpa ukuran\n  qty       Int      @default(0)\n  updatedAt DateTime @updatedAt\n  createdAt DateTime @default(now())\n\n  product   Product         @relation(fields: [productId], references: [id], onDelete: Cascade)\n  color     Color?          @relation(fields: [colorId], references: [id], onDelete: Cascade)\n  size      Size?           @relation(fields: [sizeId], references: [id], onDelete: Cascade)\n  movements StockMovement[]\n\n  @@unique([productId, colorId, sizeId])\n  @@map(\"stocks\")\n}\n\n/// Mutasi stok — sheet MASUK/KELUAR + koreksi scan.\nmodel StockMovement {\n  id        String            @id @default(cuid())\n  stockId   String\n  type      StockMovementType\n  qty       Int // selalu positif; arah ditentukan type\n  refType   String? // ORDER, PICKING, SHIPMENT, RETURN, PRODUCTION, ADJUSTMENT\n  refId     String?\n  userId    String? // user yang melakukan\n  note      String?\n  createdAt DateTime          @default(now())\n\n  stock Stock @relation(fields: [stockId], references: [id], onDelete: Cascade)\n  user  User? @relation(fields: [userId], references: [id])\n\n  @@index([stockId, createdAt])\n  @@index([createdAt])\n  @@index([type])\n  @@map(\"stock_movements\")\n}\n\n/// Log scan barang — sheet \"Scan\" (input scanner hitung cepat).\nmodel StockScan {\n  id        String   @id @default(cuid())\n  code      String // kode/label yang discan\n  qty       Int      @default(1)\n  note      String?\n  userId    String?\n  createdAt DateTime @default(now())\n\n  @@index([createdAt])\n  @@map(\"stock_scans\")\n}\n\n// ---------------------------------------------------------------------------\n// PENJUALAN\n// ---------------------------------------------------------------------------\n\n/// Reseller — sheet HITUNGAN RESELLER (JOING, PAJIM, RAJIL, RANGGA, REZA).\nmodel Reseller {\n  id        String   @id @default(cuid())\n  code      String   @unique\n  name      String\n  phone     String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  prices   ResellerPrice[]\n  orders   SalesOrder[]\n  payments ResellerPayment[]\n\n  @@map(\"resellers\")\n}\n\n/// Harga jual PER RESELLER (beda per orang — temuan #4).\nmodel ResellerPrice {\n  resellerId String\n  productId  String\n  price      Int // Rupiah\n  updatedAt  DateTime @updatedAt\n\n  reseller Reseller @relation(fields: [resellerId], references: [id], onDelete: Cascade)\n  product  Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@id([resellerId, productId])\n  @@map(\"reseller_prices\")\n}\n\n/// Order penjualan semua channel (dropship, reseller, marketplace, live).\n/// NOTE: sheet \"SO\" — jika ternyata Stok Opname (bukan Surat Order),\n/// tambahkan model StockOpname terpisah (lihat dokumen, pertanyaan #2).\nmodel SalesOrder {\n  id             String       @id @default(cuid())\n  orderNumber    String       @unique // ORD-YYYYMMDD-001 (no urut internal)\n  date           DateTime\n  entityId       String? // brand asal (Kebaya Authentik / Glamore)\n  channel        SalesChannel\n  resellerId     String? // wajib saat channel = RESELLER\n  status         OrderStatus  @default(PENDING)\n  totalQty       Int          @default(0) // Σ orderedQty item — dihitung aplikasi\n  totalAmount    Int          @default(0) // Σ subtotal item — dihitung aplikasi\n  customerName   String?\n  customerPhone  String?\n  shippingNumber String?      @unique // RESI — cegah shipment ganda\n  note           String?\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n\n  entity   Entity?          @relation(fields: [entityId], references: [id])\n  reseller Reseller?        @relation(fields: [resellerId], references: [id])\n  items    SalesOrderItem[]\n  picking  Picking?\n  shipment Shipment?\n  returns  Return[]\n\n  @@index([date])\n  @@index([status])\n  @@index([channel, date])\n  @@index([resellerId])\n  @@map(\"sales_orders\")\n}\n\nmodel SalesOrderItem {\n  id            String         @id @default(cuid())\n  orderId       String\n  productId     String\n  colorId       String?\n  sizeId        String?\n  orderedQty    Int\n  unitPrice     Int // snapshot harga saat order — tidak ikut ubah master\n  subtotal      Int // orderedQty × unitPrice — disimpan, bukan dihitung ulang\n  order         SalesOrder     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product       Product        @relation(fields: [productId], references: [id])\n  color         Color?         @relation(fields: [colorId], references: [id])\n  size          Size?          @relation(fields: [sizeId], references: [id])\n  pickingItems  PickingItem[]\n  shipmentItems ShipmentItem[]\n  returnItems   ReturnItem[]\n\n  @@index([orderId])\n  @@index([productId])\n  @@map(\"sales_order_items\")\n}\n\n/// Pembayaran reseller → pelunasan piutang (kolom BAYAR, \"SISA PIUTANG\").\n/// Piutang berjalan = Σ order RESELLER − Σ pembayaran (dihitung aplikasi).\nmodel ResellerPayment {\n  id         String   @id @default(cuid())\n  resellerId String\n  date       DateTime\n  amount     Int // Rupiah\n  method     String? // CASH / TRANSFER / QRIS\n  note       String?\n  createdAt  DateTime @default(now())\n\n  reseller Reseller @relation(fields: [resellerId], references: [id], onDelete: Cascade)\n\n  @@index([resellerId, date])\n  @@map(\"reseller_payments\")\n}\n\n// ---------------------------------------------------------------------------\n// HR — PRESENSI, GAJI, BONUS\n// ---------------------------------------------------------------------------\n\n/// Presensi harian — sheet EGA/GEFIRA/EKI/RADIT. Kode J1-J4 → AttendanceCode.\n/// sesi1..3 = nilai sesi host live (SESI 1/2/3).\nmodel Attendance {\n  id            String         @id @default(cuid())\n  employeeId    String\n  date          DateTime       @db.Date\n  code          AttendanceCode @default(WORK)\n  sesi1         Int?\n  sesi2         Int?\n  sesi3         Int?\n  overtimeHours Decimal?       @db.Decimal(4, 1)\n  note          String?\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n\n  employee Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n\n  @@unique([employeeId, date])\n  @@map(\"attendances\")\n}\n\n/// Target penjualan bulanan (bonus) — sheet BONUS / Sheet1.\n/// Contoh: targetPcs 2000, targetAmount 6.875.000, komisi 2%, up-target 3%.\nmodel SalesTarget {\n  id            String   @id @default(cuid())\n  year          Int\n  month         Int // 1-12\n  targetPcs     Int      @default(0)\n  targetAmount  Int      @default(0) // Rupiah\n  commissionPct Decimal  @default(0) @db.Decimal(5, 2) // persen\n  upTargetPct   Decimal  @default(0) @db.Decimal(5, 2)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  @@unique([year, month])\n  @@map(\"sales_targets\")\n}\n\n/// Gaji bulanan per karyawan — sheet \"rumus\" (pokok + tunjangan + bonus − potongan).\nmodel Payroll {\n  id         String        @id @default(cuid())\n  employeeId String\n  year       Int\n  month      Int\n  basePay    Int           @default(0) // gaji pokok prorata hari kerja\n  transport  Int           @default(0)\n  overtime   Int           @default(0)\n  bonus      Int           @default(0)\n  deduction  Int           @default(0) // potongan (ijin/alfa, dll)\n  total      Int           @default(0) // Σ — dihitung aplikasi\n  status     PayrollStatus @default(DRAFT)\n  paidAt     DateTime?\n  note       String?\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n\n  employee Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade)\n\n  @@unique([employeeId, year, month])\n  @@map(\"payrolls\")\n}\n\n// ---------------------------------------------------------------------------\n// KEUANGAN — KAS (menu baru, dari 2 file cash Flow)\n// ---------------------------------------------------------------------------\n\n/// Cash flow harian per entitas. Saldo berjalan dihitung aplikasi\n/// (Σ IN − Σ OUT s.d. tanggal) — tidak disimpan per baris.\nmodel CashTransaction {\n  id          String       @id @default(cuid())\n  entityId    String\n  date        DateTime     @db.Date\n  description String\n  receiptNo   String? // No Kwitansi/Struk\n  type        CashFlowType\n  category    CashCategory @default(OTHER)\n  amount      Int // Rupiah, selalu positif\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  entity Entity @relation(fields: [entityId], references: [id])\n\n  @@index([entityId, date])\n  @@map(\"cash_transactions\")\n}\n\n// =============================================================================\n// ORDER & RESI (STEP 4 — workflow marketplace: Order → Picking → Kirim → Stok)\n// =============================================================================\n\n// Picking — draft pengambilan barang sebelum kirim. actualQty = qty riil.\nmodel Picking {\n  id           String    @id @default(cuid())\n  orderId      String    @unique // 1 order = 1 picking\n  note         String?\n  pickedByUser String?\n  pickedAt     DateTime? // saat warehouse submit actual qty\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  order    SalesOrder    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  pickedBy User?         @relation(fields: [pickedByUser], references: [id])\n  items    PickingItem[]\n\n  @@map(\"pickings\")\n}\n\nmodel PickingItem {\n  id          String  @id @default(cuid())\n  pickingId   String\n  orderItemId String  @unique // 1 baris item order = 1 baris picking\n  actualQty   Int     @default(0) // actual qty (bisa < orderedQty dgn flag eksplisit)\n  note        String?\n\n  picking   Picking        @relation(fields: [pickingId], references: [id], onDelete: Cascade)\n  orderItem SalesOrderItem @relation(fields: [orderItemId], references: [id], onDelete: Cascade)\n\n  @@index([pickingId])\n  @@map(\"picking_items\")\n}\n\n// Shipment — konfirmasi kirim. SATU-SATUNYA tempat stok barang jadi berkurang.\n// shippingNumber unique → double shipment mustahil.\nmodel Shipment {\n  id             String   @id @default(cuid())\n  orderId        String   @unique\n  shippingNumber String   @unique // resi (sinkron dengan SalesOrder.shippingNumber)\n  shippedAt      DateTime @default(now())\n  userId         String? // operator yg konfirmasi\n  createdAt      DateTime @default(now())\n\n  order SalesOrder     @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  user  User?          @relation(fields: [userId], references: [id])\n  items ShipmentItem[]\n\n  @@index([shippedAt])\n  @@map(\"shipments\")\n}\n\nmodel ShipmentItem {\n  id          String @id @default(cuid())\n  shipmentId  String\n  orderItemId String @unique // dikirim = actual qty hasil picking\n  qty         Int // qty terkirim (dari picking actualQty)\n\n  shipment  Shipment       @relation(fields: [shipmentId], references: [id], onDelete: Cascade)\n  orderItem SalesOrderItem @relation(fields: [orderItemId], references: [id])\n\n  @@index([shipmentId])\n  @@map(\"shipment_items\")\n}\n\n// Retur — penerimaan barang retur. TIDAK otomatis nambah stok:\n// stok hanya naik bila layak jual (RETURN_IN).\nmodel Return {\n  id        String   @id @default(cuid())\n  orderId   String\n  date      DateTime @default(now())\n  userId    String? // penerima retur\n  note      String?\n  createdAt DateTime @default(now())\n\n  order SalesOrder   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  user  User?        @relation(fields: [userId], references: [id])\n  items ReturnItem[]\n\n  @@index([orderId])\n  @@index([date])\n  @@map(\"returns\")\n}\n\nmodel ReturnItem {\n  id          String  @id @default(cuid())\n  returnId    String\n  orderItemId String\n  qty         Int // jumlah diterima\n  restock     Boolean @default(false) // layak jual → RETURN_IN (stok naik)\n\n  retur     Return         @relation(fields: [returnId], references: [id], onDelete: Cascade)\n  orderItem SalesOrderItem @relation(fields: [orderItemId], references: [id])\n\n  @@index([returnId])\n  @@map(\"return_items\")\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

